func (c *Conn) SetReadDeadline(t time.Time) error {
    c.mu.Lock()
    c.readDeadline = t
    // Signal any blocked Read to re-check
    if c.deadlineCh != nil {
        close(c.deadlineCh)
    }
    c.deadlineCh = make(chan struct{})
    c.mu.Unlock()
    return nil
}

